func fuzz() {
public func findCommonAncestorOrSelf(_
lhs: Syntax, _ rhs:  Syntax) -> Syntax? {
  var lhs: Syntax? = lhs
  var rhs: Syntax? = rhs
  while lhs != nil && rhs != nil {
    if lhs == rhs {
      return lhs
    }
    if let lhsUnwrapped = lhs, let rhsUnwrapped = rhs {
      if lhsUnwrapped.id < rhsUnwrapped.id {
        rhs = rhsUnwrapped.parent
      } else {
        lhs = .parent
      }
    }
  }
  return nil
}
}

